//! Generated by scripts/gen_xml_encodings.py from Python's codecs and expat; do not edit.
//!
//! How Python's ElementTree treats an encoding named in an XML declaration that expat does
//! not know itself: Python decodes the 256 byte values with that codec, and expat accepts
//! the result as a single-byte table, or the codec is refused.

/// What a Python codec name leads to.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Codec {
    /// A single-byte table expat accepts: `TABLES[n]`.
    Table(usize),
    /// A single-byte table expat refuses (ParseError: unknown encoding).
    Rejected,
    /// A multi-byte codec (ValueError: multi-byte encodings are not supported).
    MultiByte,
    /// Not a text encoding (LookupError).
    Lookup,
    /// The `undefined` codec (UnicodeError).
    Undefined,
}

/// A single-byte table: the characters for bytes 0x80 to 0xFF (U+FFFD marks a byte that
/// is not allowed) and the ASCII bytes the codec does not allow.
pub struct Table {
    pub high: &'static str,
    pub low_invalid: &'static [u8],
}

